    priceDecimal() {
      return val => {
        if (val !== parseInt(val)) return val.slice(-2);else return '00';
      };
    },
    // 价格整数
    priceInt() {
      return val => {
        if (val !== parseInt(val)) return val.split('.')[0];else return val;
      };
    }
